// CreateTableWithDBType creates the Sales_Header table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *SalesHeader) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, SalesHeaderTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetSalesHeaderPostgresTableSchema()
	} else {
		schema = GetSalesHeaderTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Sales_Header table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *SalesHeader) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, SalesHeaderTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, no)`,
		fmt.Sprintf("%s$Sales_Header$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, sell_to_customer_no)`,
		fmt.Sprintf("%s$Sales_Header$customer", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index customer: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, combine_shipments, bill_to_customer_no, currency_code)`,
		fmt.Sprintf("%s$Sales_Header$combine_shipments", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index combine_shipments: %w", err)
	}
	var keys []sift.Key
	for _, spec := range salesHeaderSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, SalesHeaderTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, SalesHeaderTableName, keys)
}

// salesHeaderSIFTSpecs are the table's keys with sum_index_fields
func salesHeaderSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *SalesHeader) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, SalesHeaderTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range salesHeaderSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, SalesHeaderTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: SalesHeaderTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, SalesHeaderTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

